Get-ChildItem -Recurse -File | Where-Object { $_.FullName -notmatch '\\node_modules\\' -and $_.FullName -notmatch '\\.git\\' -and $_.FullName -notmatch '\\.gemini\\' } | Sort-Object Length -Descending | Select-Object Name, @{Name='SizeMB';Expression={[math]::Round($_.Length / 1MB, 2)}}, @{Name='Directory';Expression={$_.Directory.Name}} | Select-Object -First 30 | Format-Table -AutoSize
